export function evaluate({ inputs, time }) {
  const launchSpeed = inputs.launchSpeed;
  const g = 9.8;
  const apexTime = launchSpeed / g;
  const apexHeight = (launchSpeed * launchSpeed) / (2 * g);
  const t = Math.min(time, 2 * apexTime);
  const velocity = launchSpeed - g * t;
  const height = launchSpeed * t - 0.5 * g * t * t;

  let motionStateText = "Still for an instant";
  if (velocity > 0.05) {
    motionStateText = "Moving up";
  } else if (velocity < -0.05) {
    motionStateText = "Moving down";
  }
  const gravityStateText = "Gravity pulls down";

  const xCenter = 320;
  const yLaunch = 350;
  const scaleY = 160; // pixels per meter
  const ballY = yLaunch - height * scaleY;

  const frameObjects = [];

  // Lane / Panel background
  const lane = sdk.panel({
    id: "lane.toss",
    x: 40,
    y: 35,
    w: 560,
    h: 360,
    title: "Vertical Toss",
    state: motionStateText + " • " + gravityStateText
  });
  frameObjects.push(...lane);

  // Y Axis for height scale
  frameObjects.push(sdk.axis("axis.height", {
    x: 140,
    y: 350,
    length: 270,
    orientation: "y",
    min: 0,
    max: 1.5,
    ticks: [0, 0.5, 1.0, 1.5],
    label: "Height",
    unit: "m"
  }));

  // Launch-height guide (ground line)
  frameObjects.push(sdk.line("guide.launch", 150, yLaunch, 490, yLaunch, {
    role: "neutral",
    opacity: 0.5
  }));
  frameObjects.push(sdk.text("guide.label", 495, yLaunch + 4, "Launch height", {
    align: "start",
    role: "neutral"
  }));

  // Ball
  frameObjects.push(sdk.circle("ball.toss", xCenter, ballY, 28, {
    role: "learner"
  }));

  // Motion arrow (velocity, blue)
  const vAbs = Math.abs(velocity);
  if (vAbs >= 0.05) {
    const dir = velocity > 0 ? "up" : "down";
    frameObjects.push(...sdk.vector("vec.v", {
      x: xCenter - 30,
      y: ballY
    }, {
      value: vAbs,
      direction: dir,
      scale: 18,
      minLength: 12,
      label: "v",
      role: "prediction"
    }));
  }

  // Gravity arrow (acceleration, constant downward, warm/warning)
  frameObjects.push(...sdk.vector("vec.a", {
    x: xCenter + 30,
    y: ballY
  }, {
    value: g,
    direction: "down",
    scale: 4,
    minLength: 16,
    label: "a",
    role: "warning"
  }));

  // Callout text box beside the ball
  const calloutLines = [motionStateText, gravityStateText];
  frameObjects.push(...sdk.callout(xCenter + 80, ballY - 18, calloutLines, {
    id: "callout.toss",
    role: "tutor"
  }));

  return {
    frame: sdk.frame(frameObjects),
    quantities: {
      launchSpeed: launchSpeed,
      gravity: g,
      apexTime: apexTime,
      apexHeight: apexHeight,
      velocity: velocity,
      height: height
    },
    readouts: [
      { id: "motionState", value: motionStateText },
      { id: "gravityState", value: gravityStateText }
    ]
  };
}
